using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com";

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    /// <summary>
    /// Creates the chat client used by the agent under test.
    /// Wraps with telemetry so spans are captured automatically.
    /// </summary>
    public static IChatClient CreateChatClient()
    {
        var inner = new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential())
            .GetChatClient(DeploymentName)
            .AsIChatClient();

        // Wire OpenTelemetry-compatible telemetry into the pipeline
        return new ChatClientBuilder(inner)
            .UseOpenTelemetry()
            .Build();
    }

    /// <summary>
    /// Creates the chat client used as a judge for quality evaluators.
    /// </summary>
    public static IChatClient CreateJudgeClient()
    {
        var judgeDeployment =
            Environment.GetEnvironmentVariable("AZURE_OPENAI_JUDGE_DEPLOYMENT") ?? "gpt-4o";

        return new AzureOpenAIClient(new Uri(Endpoint), new DefaultAzureCredential())
            .GetChatClient(judgeDeployment)
            .AsIChatClient();
    }

    /// <summary>
    /// Quality evaluators: relevance, coherence, fluency, groundedness.
    /// </summary>
    public static IList<IEvaluator> GetQualityEvaluators()
    {
        using var judge = CreateJudgeClient();
        return
        [
            new RelevanceEvaluator(judge),
            new CoherenceEvaluator(judge),
            new FluencyEvaluator(judge),
            new GroundednessEvaluator(judge),
        ];
    }

    /// <summary>
    /// Builds the reporting configuration for storing eval results on disk.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(
        string scenarioName,
        IList<IEvaluator>? evaluators = null)
    {
        var storageDir = Path.Combine(
            Directory.GetCurrentDirectory(), ".eval-results", scenarioName);

        return new ReportingConfiguration(
            storageRootPath: storageDir,
            evaluators: evaluators ?? GetQualityEvaluators());
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits the expected
/// OpenTelemetry spans/attributes during a chat turn.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly ActivitySource Source = new("MyApp.Evals.Telemetry");

    [TestMethod]
    public async Task Agent_EmitsGenAiSpans()
    {
        var collectedActivities = new List<Activity>();

        using var listener = new ActivityListener
        {
            ShouldListenTo = src => src.Name.Contains("OpenAI") || src.Name.Contains("Microsoft.Extensions.AI"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => collectedActivities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        using var client = EvalConfig.CreateChatClient();

        var response = await client.GetResponseAsync("What is 2 + 2?");

        Assert.IsTrue(
            collectedActivities.Count > 0,
            "Expected at least one Activity/span from the chat client pipeline.");

        var genAiSpan = collectedActivities.FirstOrDefault(
            a => a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase));

        Assert.IsNotNull(genAiSpan, "Expected a 'chat' span from the telemetry pipeline.");
        Assert.IsTrue(
            genAiSpan.Duration > TimeSpan.Zero,
            "Span duration should be positive.");
    }

    [TestMethod]
    public async Task Agent_TracksTokenUsage()
    {
        var collectedActivities = new List<Activity>();

        using var listener = new ActivityListener
        {
            ShouldListenTo = src => true,
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = activity => collectedActivities.Add(activity),
        };
        ActivitySource.AddActivityListener(listener);

        using var client = EvalConfig.CreateChatClient();

        var response = await client.GetResponseAsync("Say hello.");

        // Verify usage is present in the response
        var lastMessage = response.Messages.LastOrDefault();
        Assert.IsNotNull(response, "Response should not be null.");

        // Verify telemetry captured spans with token attributes
        var hasTokenInfo = collectedActivities.Any(a =>
            a.Tags.Any(t => t.Key.Contains("token", StringComparison.OrdinalIgnoreCase)));

        Assert.IsTrue(hasTokenInfo, "Expected token usage information in telemetry spans.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: runs judge-model evaluators (relevance, coherence,
/// fluency, groundedness) against agent responses and reports scores.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_reportingConfig;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_reportingConfig = EvalConfig.CreateReportingConfig("quality");
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        using var chatClient = EvalConfig.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management skills?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantReply = response.Messages.Last(m => m.Role == ChatRole.Assistant);

        // Build the evaluation turn
        var turn = new EvaluationTurn(messages, assistantReply);

        // Run all quality evaluators
        var results = await s_reportingConfig!.EvaluateAsync(turn);

        // Assert minimum quality thresholds
        AssertScore(results, nameof(RelevanceEvaluator), minScore: 3);
        AssertScore(results, nameof(CoherenceEvaluator), minScore: 3);
        AssertScore(results, nameof(FluencyEvaluator), minScore: 3);
    }

    [TestMethod]
    public async Task CoachResponse_IsGrounded()
    {
        using var chatClient = EvalConfig.CreateChatClient();

        var context = "Research shows that time-blocking and the Pomodoro technique improve focus.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a coaching assistant. Use this context: {context}"),
            new(ChatRole.User, "What techniques can help me focus better?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantReply = response.Messages.Last(m => m.Role == ChatRole.Assistant);

        var turn = new EvaluationTurn(messages, assistantReply, context: context);
        var results = await s_reportingConfig!.EvaluateAsync(turn);

        AssertScore(results, nameof(GroundednessEvaluator), minScore: 3);
    }

    private static void AssertScore(
        EvaluationResult results,
        string evaluatorName,
        int minScore)
    {
        var metric = results.Metrics.FirstOrDefault(
            m => m.Key.Contains(evaluatorName, StringComparison.OrdinalIgnoreCase));

        Assert.IsTrue(
            metric.Value is not null,
            $"No metric found for {evaluatorName}.");

        var numericResult = metric.Value as NumericMetric;
        Assert.IsNotNull(numericResult, $"{evaluatorName} should produce a NumericMetric.");
        Assert.IsTrue(
            numericResult.Value >= minScore,
            $"{evaluatorName} scored {numericResult.Value}, expected >= {minScore}.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations
/// and reports side-by-side quality scores for regression detection.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly (string Deployment, string Label)[] Models =
    [
        (Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini", "baseline"),
        (Environment.GetEnvironmentVariable("AZURE_OPENAI_COMPARE_DEPLOYMENT") ?? "gpt-4o", "candidate"),
    ];

    private static readonly string[] Prompts =
    [
        "How do I set SMART goals for career growth?",
        "What's the best way to give constructive feedback to a teammate?",
        "Suggest a daily routine for improving productivity.",
    ];

    [TestMethod]
    public async Task CompareModels_QualityScores()
    {
        var allResults = new Dictionary<string, List<EvaluationResult>>();

        foreach (var (deployment, label) in Models)
        {
            var config = EvalConfig.CreateReportingConfig($"compare-{label}");
            var client = CreateClientForDeployment(deployment);
            var results = new List<EvaluationResult>();

            foreach (var prompt in Prompts)
            {
                var messages = new List<ChatMessage>
                {
                    new(ChatRole.System, "You are a helpful coaching assistant."),
                    new(ChatRole.User, prompt),
                };

                var response = await client.GetResponseAsync(messages);
                var reply = response.Messages.Last(m => m.Role == ChatRole.Assistant);

                var turn = new EvaluationTurn(messages, reply);
                var result = await config.EvaluateAsync(turn);
                results.Add(result);
            }

            allResults[label] = results;
            client.Dispose();
        }

        // Compare: candidate should not regress more than 1 point on average vs baseline
        AssertNoRegression(allResults, nameof(RelevanceEvaluator), maxDrop: 1.0);
        AssertNoRegression(allResults, nameof(CoherenceEvaluator), maxDrop: 1.0);
        AssertNoRegression(allResults, nameof(FluencyEvaluator), maxDrop: 1.0);
    }

    private static IChatClient CreateClientForDeployment(string deployment)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://your-resource.openai.azure.com";

        var client = new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint), new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        return new ChatClientBuilder(client)
            .UseOpenTelemetry()
            .Build();
    }

    private static void AssertNoRegression(
        Dictionary<string, List<EvaluationResult>> allResults,
        string evaluatorName,
        double maxDrop)
    {
        var baselineAvg = AverageScore(allResults["baseline"], evaluatorName);
        var candidateAvg = AverageScore(allResults["candidate"], evaluatorName);

        Assert.IsTrue(
            candidateAvg >= baselineAvg - maxDrop,
            $"{evaluatorName} regression detected: baseline={baselineAvg:F2}, candidate={candidateAvg:F2}, max allowed drop={maxDrop}");
    }

    private static double AverageScore(List<EvaluationResult> results, string evaluatorName)
    {
        var scores = results
            .SelectMany(r => r.Metrics)
            .Where(m => m.Key.Contains(evaluatorName, StringComparison.OrdinalIgnoreCase))
            .Select(m => m.Value as NumericMetric)
            .Where(n => n is not null)
            .Select(n => n!.Value)
            .ToList();

        return scores.Count > 0 ? scores.Average() : 0;
    }
}

