using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: runs judge-model evaluators (relevance, coherence,
/// fluency, groundedness) against agent responses and reports scores.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_reportingConfig;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        s_reportingConfig = EvalConfig.CreateReportingConfig("quality");
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        using var chatClient = EvalConfig.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management skills?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantReply = response.Messages.Last(m => m.Role == ChatRole.Assistant);

        // Build the evaluation turn
        var turn = new EvaluationTurn(messages, assistantReply);

        // Run all quality evaluators
        var results = await s_reportingConfig!.EvaluateAsync(turn);

        // Assert minimum quality thresholds
        AssertScore(results, nameof(RelevanceEvaluator), minScore: 3);
        AssertScore(results, nameof(CoherenceEvaluator), minScore: 3);
        AssertScore(results, nameof(FluencyEvaluator), minScore: 3);
    }

    [TestMethod]
    public async Task CoachResponse_IsGrounded()
    {
        using var chatClient = EvalConfig.CreateChatClient();

        var context = "Research shows that time-blocking and the Pomodoro technique improve focus.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a coaching assistant. Use this context: {context}"),
            new(ChatRole.User, "What techniques can help me focus better?"),
        };

        var response = await chatClient.GetResponseAsync(messages);
        var assistantReply = response.Messages.Last(m => m.Role == ChatRole.Assistant);

        var turn = new EvaluationTurn(messages, assistantReply, context: context);
        var results = await s_reportingConfig!.EvaluateAsync(turn);

        AssertScore(results, nameof(GroundednessEvaluator), minScore: 3);
    }

    private static void AssertScore(
        EvaluationResult results,
        string evaluatorName,
        int minScore)
    {
        var metric = results.Metrics.FirstOrDefault(
            m => m.Key.Contains(evaluatorName, StringComparison.OrdinalIgnoreCase));

        Assert.IsTrue(
            metric.Value is not null,
            $"No metric found for {evaluatorName}.");

        var numericResult = metric.Value as NumericMetric;
        Assert.IsNotNull(numericResult, $"{evaluatorName} should produce a NumericMetric.");
        Assert.IsTrue(
            numericResult.Value >= minScore,
            $"{evaluatorName} scored {numericResult.Value}, expected >= {minScore}.");
    }
}

